<template><Dialog v-model="visible" title="导入学习记录" width="520px"><el-upload ref="uploadRef" v-model:file-list="files" :action="url" :headers="headers" :auto-upload="false" :limit="1" accept=".xls,.xlsx" drag :on-success="onSuccess" :on-error="onError"><Icon icon="ep:upload" /><div class="el-upload__text">拖入文件或点击选择</div><template #tip><div>按任务ID、员工姓名和员工科室导入。<el-link type="primary" @click="downloadTemplate">下载模板</el-link></div></template></el-upload><template #footer><el-button type="primary" :loading="loading" @click="submit">确定</el-button><el-button @click="visible=false">取消</el-button></template></Dialog></template>
<script setup lang="ts">
import { EducationRecordApi } from '@/api/yideyifeng/education/record';import { getAccessToken,getTenantId } from '@/utils/auth';import download from '@/utils/download'
const message=useMessage(),visible=ref(false),loading=ref(false),uploadRef=ref(),files=ref<any[]>([]),headers=ref<Record<string,string>>();const url=import.meta.env.VITE_BASE_URL+import.meta.env.VITE_API_URL+'/yideyifeng/education-record/import'
const open=()=>{visible.value=true;files.value=[]};defineExpose({open});const emit=defineEmits(['success'])
const submit=()=>{if(!files.value.length){message.error('请选择文件');return}headers.value={Authorization:'Bearer '+getAccessToken(),'tenant-id':String(getTenantId())};loading.value=true;nextTick(()=>uploadRef.value?.submit())}
const onSuccess=(res:any)=>{loading.value=false;if(res.code!==0){message.error(res.msg);return}const d=res.data;message.alert(`成功 ${d.successCount} 条，失败 ${d.failureCount} 条<br/>${(d.failureMessages||[]).join('<br/>')}`);visible.value=false;emit('success')};const onError=()=>{loading.value=false;message.error('导入失败')};const downloadTemplate=async()=>download.excel(await EducationRecordApi.getImportTemplate(),'学习记录导入模板.xlsx')
</script>
